14	export function run(args, { input, stdinFd, cwd, timeout = 60000 } = {}) {
15	  const opts = {
16	    cwd,
17	    timeout,
18	    maxBuffer: 64 * 1024 * 1024,
19	    encoding: 'utf8',
20	  };
21	  if (stdinFd !== undefined) {
22	    opts.stdio = [stdinFd, 'pipe', 'pipe'];
23	  } else {
24	    opts.input = input === undefined ? '' : input;
25	  }
26	  const r = spawnSync(process.execPath, [CLI, ...args], opts);
27	  return { status: r.status, stdout: r.stdout, stderr: r.stderr };
28	}
