30	// Creates a temp dir and registers cleanup for the calling suite.
31	export function tempDir() {
32	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'jsonpatch-cli-'));
33	  after(() => {
34	    fs.rmSync(dir, { recursive: true, force: true });
35	  });
36	  return dir;
37	}
