57	// Valid JSON '[]' padded with trailing spaces so that prefix + content is `total` bytes.
58	export function padded(total, prefix = Buffer.alloc(0)) {
59	  const body = Buffer.from('[]');
60	  const fill = Buffer.alloc(total - prefix.length - body.length, 0x20);
61	  return Buffer.concat([prefix, body, fill]);
62	}
